#!/usr/bin/env bash
set -euo pipefail
umask 077

base=cad7d4b5dabda8f7f8b34270890b467039146384
revision=e1f954a69d32ba518b16e7a309a51fb9fe517e59
url=https://135-106-227-179.sslip.io
root=/opt/ventry
site="$root/site"
files=(company-nav.js home-company.css index.html version.json)

test -d "$site"
exec 9>"$root/.homepage-publish.lock"
flock -n 9 || { echo 'Another homepage publication is running.' >&2; exit 1; }
before="$(python3 -c 'import json, sys; print(json.load(open(sys.argv[1]))["commit"])' "$site/version.json")"
if [[ "$before" != "$base" && "$before" != "$revision" ]]; then
  printf 'Unexpected server revision: %s\n' "$before" >&2
  exit 1
fi

stage="$(mktemp -d "$root/.homepage-stage.XXXXXXXX")"
backup=''
applied=()
cleanup() {
  local rc=$? file
  trap - EXIT
  if (( rc != 0 && ${#applied[@]} )); then
    printf 'HTTPS verification failed. Restoring files from %s\n' "$backup" >&2
    for file in "${applied[@]}"; do
      if ! cp -p -- "$backup/$file" "$stage/restore-$file" ||
         ! mv -fT -- "$stage/restore-$file" "$site/$file"; then
        printf 'RESTORE FAILED: %s\n' "$file" >&2
      fi
    done
  fi
  rm -rf -- "$stage"
  exit "$rc"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
test "$(stat -c %d "$stage")" = "$(stat -c %d "$site")"

python3 - "$stage" "$revision" <<'PY'
import base64
import gzip
import hashlib
import json
import sys
from pathlib import Path

entries = json.loads(gzip.decompress(base64.b64decode('')))
target = Path(sys.argv[1])
for name, expected, content in entries:
    data = base64.b64decode(content)
    actual = hashlib.sha1(f"blob {len(data)}\0".encode() + data).hexdigest()
    if actual != expected:
        raise SystemExit(f"Unexpected Git blob for {name}")
    (target / name).write_bytes(data)
(target / "version.json").write_text(json.dumps({"commit": sys.argv[2]}))
PY

verify_https() {
  local path file
  for file in "${files[@]}"; do
    path="/$file"
    if [[ "$file" == index.html ]]; then path=/; fi
    curl -fsS --max-time 12 --retry 1 -H 'Cache-Control: no-cache' "$url$path" -o "$stage/response"
    cmp "$stage/$file" "$stage/response"
  done
  [[ "$(curl -fsS --max-time 12 "$url/healthz")" == ok ]]
  curl -fsS --max-time 12 "$url/projects/raschet/" -o /dev/null
}

if [[ "$before" == "$revision" ]]; then
  verify_https
  printf 'VENTRY_ALREADY_PUBLISHED %s\n' "$revision"
  exit 0
fi

backup="$(mktemp -d "$root/.homepage-backup.XXXXXXXX")"
for file in "${files[@]}"; do
  cp -p -- "$site/$file" "$backup/$file"
  chmod --reference="$backup/$file" "$stage/$file"
  chown --reference="$backup/$file" "$stage/$file"
  cp -p -- "$stage/$file" "$stage/install-$file"
done
for file in "${files[@]}"; do
  applied+=("$file")
  mv -fT -- "$stage/install-$file" "$site/$file"
done
verify_https
printf 'VENTRY_PUBLISHED %s\nBackup: %s\n' "$revision" "$backup"
